--
-- Structure de la table `blog_articles`
--

CREATE TABLE `blog_articles` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `content` text NOT NULL,
  `image` longblob DEFAULT NULL,
  `author_id` bigint(20) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `blog_articles`
--

INSERT INTO `blog_articles` (`id`, `title`, `slug`, `content`, `image`, `author_id`, `created_at`, `updated_at`) VALUES
(1, 'Les Mystères du One Piece : Que Renferme le Trésor de Gol D. Roger ?', 'les-mysteres-du-one-piece-que-renferme-le-tresor-de-gol-d-roger', 'Le légendaire trésor connu sous le nom de One Piece continue de fasciner les fans du monde entier. Mais que contient réellement ce trésor que Gol D. Roger a laissé derrière lui ? Cet article explore les théories populaires, des armes antiques aux secrets des Royaumes Perdus. Les indices disséminés dans l’histoire laissent penser que le One Piece pourrait bien être plus qu’une simple richesse matérielle. Est-il un message pour changer le monde ? Une clé vers un savoir oublié ? Découvrons ensemble les hypothèses les plus captivantes sur ce mystère.', , 1, '2024-06-10 09:20:00', '2024-06-10 09:20:00');
INSERT INTO `blog_articles` (`id`, `title`, `slug`, `content`, `image`, `author_id`, `created_at`, `updated_at`) VALUES
(2, 'Les Fruits du Démon les Plus Puissants de One Piece', 'les-fruits-du-demon-les-plus-puissants-de-one-piece', 'Dans l’univers de One Piece, les Fruits du Démon confèrent des pouvoirs incroyables à ceux qui les consomment. Certains de ces fruits se démarquent par leur puissance démesurée. Dans cet article, nous passons en revue les Fruits du Démon les plus impressionnants, du Gomu Gomu no Mi de Luffy au Yami Yami no Mi de Barbe Noire. Chacun de ces fruits possède des capacités qui peuvent bouleverser l’équilibre des forces en mer, mais aussi mettre en danger celui qui les utilise. Plongeons dans le monde fascinant de ces fruits et découvrons leurs secrets.', , 5, '2024-06-10 09:20:00', '2024-06-10 09:20:00');
INSERT INTO `blog_articles` (`id`, `title`, `slug`, `content`, `image`, `author_id`, `created_at`, `updated_at`) VALUES
(3, 'La Grande Guerre de Marineford : Un Tournant Historique dans One Piece', 'la-grande-guerre-de-marineford-un-tournant-historique-dans-one-piece', 'La bataille de Marineford a marqué un tournant décisif dans le monde de One Piece. Ce combat, impliquant la Marine, les pirates et les membres de l’équipage de Barbe Blanche, a changé la face du monde. Cet article retrace les moments clés de cette bataille épique, la perte de personnages emblématiques comme Ace et Barbe Blanche, et les répercussions de cet affrontement sur le monde des pirates. Nous analysons également comment cet événement a façonné la détermination de Luffy à devenir le Roi des Pirates.', , 1, '2024-06-10 09:20:00', '2024-06-10 09:20:00');
INSERT INTO `blog_articles` (`id`, `title`, `slug`, `content`, `image`, `author_id`, `created_at`, `updated_at`) VALUES
(4, 'L’équipage de Chapeau de Paille : Héros et Personnalités Uniques', 'l-equipage-de-chapeau-de-paille-heros-et-personnalites-uniques', 'L’équipage de Chapeau de Paille est constitué de personnages aux talents divers et aux personnalités singulières. De Zoro, le bretteur sans égal, à Nami, la navigatrice experte, chaque membre joue un rôle indispensable dans la quête de Luffy pour devenir le Roi des Pirates. Cet article explore les histoires personnelles et les motivations de chaque membre, révélant pourquoi cet équipage reste l’un des plus aimés de l’univers One Piece.', , 1, '2024-06-10 09:20:00', '2024-06-10 09:20:00');
INSERT INTO `blog_articles` (`id`, `title`, `slug`, `content`, `image`, `author_id`, `created_at`, `updated_at`) VALUES
(5, 'Les Armes Antiques : Pluton, Poséidon et Uranus dans One Piece', 'les-armes-antiques-pluton-poseidon-et-uranus-dans-one-piece', 'Les Armes Antiques sont des reliques puissantes qui ont le potentiel de détruire des royaumes entiers. Dans cet article, nous explorons ce que nous savons de Pluton, Poséidon et Uranus, ces mystérieuses armes qui semblent détenir les clés du passé et du futur du monde de One Piece. Quels sont leurs pouvoirs, et pourquoi sont-elles tant convoitées par les gouvernements et les pirates ? Découvrons les secrets entourant ces armes légendaires.', , 1, '2024-06-10 09:20:00', '2024-06-10 09:20:00');
INSERT INTO `blog_articles` (`id`, `title`, `slug`, `content`, `image`, `author_id`, `created_at`, `updated_at`) VALUES
(6, 'L\'Île des Hommes-Poissons : Racisme et Rédemption dans One Piece', 'l-ile-des-hommes-poissons-racisme-et-redemption-dans-one-piece', 'L\'Île des Hommes-Poissons est bien plus qu’un simple lieu dans One Piece. Elle aborde des thèmes profonds comme le racisme, la discrimination et la recherche de rédemption. Ce chapitre de l\'histoire de Luffy et de son équipage nous montre les luttes d’un peuple marginalisé et leur quête de justice. Cet article analyse comment l\'arc de l\'Île des Hommes-Poissons reflète les problèmes sociaux du monde réel et comment les personnages comme Jinbe et la princesse Otohime symbolisent l\'espoir d\'unité et de paix.', , 1, '2024-06-10 09:20:00', '2024-06-10 09:20:00');

