DELIMITER $$
CREATE TRIGGER `update_article_slug` AFTER UPDATE ON `blog_articles` FOR EACH ROW BEGIN
    UPDATE blog_comments
    SET article_slug = NEW.slug
    WHERE article_id = NEW.id;
END
$$
DELIMITER ;

