DELIMITER $$
CREATE TRIGGER `insert_article_slug` AFTER INSERT ON `blog_comments` FOR EACH ROW BEGIN
    -- Mettre à jour article_slug dans blog_comments après insertion
    UPDATE blog_comments
    SET article_slug = (SELECT slug FROM blog_articles WHERE id = NEW.article_id)
    WHERE id = NEW.id;
END
$$
DELIMITER ;

